// Verus specifications for the meshgrid function
#[verus::spec]
fn meshgrid(x: Vec<f32>, y: Vec<f32>) -> (Vec<Vec<f32>>, Vec<Vec<f32>>) {
    // Precondition: x and y must be non-empty vectors
    // Requires: |x| >= 0 && |y| >= 0
    requires!(x.len() >= 0 && y.len() >= 0);
    
    let rows = y.len();
    let cols = x.len();

    // Create the first output matrix with repeated rows of x
    let x_grid = vec![x.clone(); rows];

    // Create the second output matrix with repeated columns of y
    let mut y_grid = vec![vec![0.0; cols]; rows];
    for i in 0..rows {
        // Invariant: 0 <= i < rows
        // Ensures: y_grid[i] is filled with y[i]
        ensures!(0 <= i && i < rows);
        for j in 0..cols {
            // Invariant: 0 <= j < cols
            // Ensures: y_grid[i][j] is set to y[i]
            ensures!(0 <= j && j < cols);
            y_grid[i][j] = y[i];
        }
    }

    // Postcondition: The output matrices have the correct dimensions
    // Ensures: |x_grid| == |y| && |x_grid[0]| == |x| && |y_grid| == |y| && |y_grid[0]| == |x|
    ensures!(x_grid.len() == rows && x_grid[0].len() == cols && y_grid.len() == rows && y_grid[0].len() == cols);

    (x_grid, y_grid)
}

fn main() {
    let x = vec![1.0, 2.0, 3.0];
    let y = vec![4.0, 5.0];
    
    let (x_grid, y_grid) = meshgrid(x, y);
    
    println!("X Grid: {:?}", x_grid);
    println!("Y Grid: {:?}", y_grid);
}